<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>HR Report Dashboard</title>

<style>
* {
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 35px 20px;
    font-family: 'Inter', Arial, sans-serif;
    background: linear-gradient(135deg, #dbeafe 0%, #eef2ff 45%, #e0f2fe 100%);
    color: #1e293b;
    min-height: 100vh;
}

.container {
    max-width: 1000px;
    margin: auto;
}

/* Header */
.header {
    background: linear-gradient(120deg, #0f172a, #1e3a8a, #2563eb);
    color: white;
    padding: 35px;
    border-radius: 18px 18px 0 0;
    position: relative;
    overflow: hidden;
}

.header h1 {
    margin: 0 0 10px;
    font-size: 27px;
    font-weight: 700;
}

.header p {
    margin: 0;
    color: #bfdbfe;
    font-size: 14px;
}

/* Decorative background */
.header::after {
    content: "";
    position: absolute;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: rgba(255,255,255,0.08);
    right: 35px;
    top: -75px;
}

/* Report panel */
.report-panel {
    background: rgba(255,255,255,0.96);
    padding: 35px;
    border: 1px solid #dbeafe;
    border-radius: 0 0 18px 18px;
    box-shadow: 0 15px 40px rgba(30,64,175,0.10);
}

/* Title */
.report-title {
    font-size: 19px;
    font-weight: 700;
    color: #142b4a;
    padding-bottom: 16px;
    border-bottom: 2px solid #dbeafe;
    margin-bottom: 25px;
}

/* Dynamic report */
.report-content {
    font-size: 14px;
    line-height: 1.8;
    color: #334155;
    overflow-wrap: anywhere;
}

.report-content h1,
.report-content h2,
.report-content h3 {
    color: #1e3a8a;
}

.report-content table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    border-radius: 10px;
    overflow: hidden;
}

.report-content th {
    background: #dbeafe;
    color: #1e40af;
    padding: 14px;
    text-align: left;
}

.report-content td {
    padding: 13px;
    border-bottom: 1px solid #e2e8f0;
}

.report-content tr:nth-child(even) {
    background: #f8fafc;
}

.report-content tr:hover {
    background: #eff6ff;
}

.report-content a {
    color: #2563eb;
    text-decoration: none;
}

/* Footer */
.footer {
    text-align: center;
    color: #64748b;
    font-size: 12px;
    margin-top: 25px;
}

@media (max-width: 600px) {
    body {
        padding: 12px;
    }

    .header, .report-panel {
        padding: 20px;
    }

    .header h1 {
        font-size: 22px;
    }

    .report-content table {
        display: block;
        overflow-x: auto;
    }
}
</style>
</head>

<body>

<div class="container">

    <header class="header">
        <h1>HR Analytics Report</h1>
        <p>Candidate Evaluation & Recruitment Insights</p>
    </header>

    <main class="report-panel">

        <div class="report-title">
            Candidate Evaluation Report
        </div>

        <div class="report-content">
            {{ $json.ReportHTML }}
        </div>

    </main>

    <footer class="footer">
        HR Management System | Automated Report
    </footer>

</div>

</body>
</html>
